"use strict";

// The vulnerable sink the advisory names. Every entrypoint in this fixture
// that reaches it does so through its OWN exported function -- never
// through module-scope code -- which is exactly what makes entrypoint ROOT
// selection the only thing standing between the analyzer and the truth.
function dangerousOp(input) {
  return "danger:" + input;
}

// A second export nothing in this fixture ever calls, for the Family C
// positive control.
function neverCalled(input) {
  return "never:" + input;
}

exports.dangerousOp = dangerousOp;
exports.neverCalled = neverCalled;
